package com.greenocean.backend.listener.planning;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import java.util.*;
/** Default dry run. Each real purge also requires an explicit approved policy reference. */
@Service @Transactional public class ListenerSupportRetention {
 private final ListenerSupportPolicy p;private final ListenerDataPolicy policy;
 public ListenerSupportRetention(ListenerSupportPolicy p,ListenerDataPolicy policy){this.p=p;this.policy=policy;}
 private record Selection(String table,String key,String where){}
 private long calendarCount(int days){long rules=p.db.queryForObject("SELECT count(*) FROM listener_calendar_rules r WHERE LEAST(COALESCE(r.retired_at,'infinity'::timestamptz),(r.valid_until+1)::timestamp AT TIME ZONE r.timezone)<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM listener_bookings b WHERE b.rule_id=r.id)",Long.class,days);long exceptions=p.db.queryForObject("SELECT count(*) FROM listener_calendar_exceptions e WHERE LEAST(e.ends_at,COALESCE(e.retired_at,'infinity'::timestamptz))<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM listener_bookings b WHERE b.exception_id=e.id)",Long.class,days);long windows=p.db.queryForObject("SELECT count(*) FROM listener_queue_coverage_windows WHERE LEAST(ends_at,COALESCE(revoked_at,'infinity'::timestamptz))<listener_support_now()-(?*INTERVAL '1 day')",Long.class,days);return rules+exceptions+windows;}
 private Map<String,Selection> selections(){var v=new LinkedHashMap<String,Selection>();v.put("BOOKING",new Selection("listener_bookings","id","status IN('COMPLETED','CANCELLED_BY_MEMBER','CANCELLED_BY_LISTENER','CANCELLED_BY_SERVICE','MEMBER_NO_SHOW','LISTENER_NO_SHOW','EXPIRED') AND COALESCE((SELECT max(e.created_at) FROM listener_booking_events e WHERE e.booking_id=listener_bookings.id),created_at)<listener_support_now()-(?*INTERVAL '1 day')"));v.put("QUEUE",new Selection("listener_wait_queue","id","status NOT IN('WAITING','OFFERED') AND GREATEST(updated_at,COALESCE((SELECT r.ended_at FROM live_support_requests r WHERE r.id=listener_wait_queue.live_request_id),updated_at))<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM live_support_requests r WHERE r.id=listener_wait_queue.live_request_id AND r.status IN('REQUESTED','ACCEPTED','ACTIVE','INTERRUPTED'))"));v.put("FEEDBACK",new Selection("listener_session_feedback","session_id","EXISTS(SELECT 1 FROM live_support_requests r WHERE r.id=listener_session_feedback.session_id AND r.status='COMPLETED' AND r.ended_at<listener_support_now()-(?*INTERVAL '1 day'))"));v.put("EXTENSION",new Selection("listener_session_extensions","id","status<>'PENDING' AND EXISTS(SELECT 1 FROM live_support_requests r WHERE r.id=listener_session_extensions.session_id AND r.status IN('COMPLETED','ENDED_SAFETY','CANCELLED','DECLINED','EXPIRED') AND r.ended_at<listener_support_now()-(?*INTERVAL '1 day'))"));return v;}
 public Map<String,Object> report(){var result=new LinkedHashMap<String,Object>();result.putAll(policy.report());var counts=new LinkedHashMap<String,Object>();for(var e:selections().entrySet()){Integer days=policy.days().get(e.getKey());counts.put(e.getKey(),days==null?"POLICY_UNSET":p.db.queryForObject("SELECT count(*) FROM "+e.getValue().table()+" WHERE "+e.getValue().where(),Long.class,days));}Integer days=policy.days().get("CALENDAR");counts.put("CALENDAR",days==null?"POLICY_UNSET":calendarCount(days));Integer duration=policy.days().get("EXTENSION");counts.put("DURATION",duration==null?"POLICY_UNSET":p.db.queryForObject("SELECT count(*) FROM live_support_requests WHERE planned_seconds IS NOT NULL AND status IN('COMPLETED','ENDED_SAFETY','EXPIRED','CANCELLED','DECLINED') AND ended_at<listener_support_now()-(?*INTERVAL '1 day')",Long.class,duration));result.put("eligibleCounts",counts);return result;}
 private void removeNotices(UUID entity){for(UUID id:p.db.queryForList("SELECT notification_id FROM listener_support_notices WHERE entity_id=? AND notification_id IS NOT NULL",UUID.class,entity))p.db.update("DELETE FROM notifications WHERE id=?",id);p.db.update("DELETE FROM listener_support_notices WHERE entity_id=?",entity);}
 @Scheduled(fixedDelayString="${greenocean.listener-support.retention-sweep-ms:1800000}") public void sweep(){if(policy.purgeEnabled())purge();}
 public Map<String,Integer> purge(){if(!policy.purgeEnabled())return Map.of();p.liveLock();p.db.queryForList("SELECT expire_live_support()");var result=new LinkedHashMap<String,Integer>();
  for(var e:selections().entrySet()){var s=e.getValue();Integer days=policy.days().get(e.getKey());int count=0;for(UUID id:p.db.queryForList("SELECT "+s.key()+" FROM "+s.table()+" WHERE "+s.where()+" ORDER BY "+s.key()+" LIMIT 100 FOR UPDATE SKIP LOCKED",UUID.class,days)){removeNotices(id);count+=p.db.update("DELETE FROM "+s.table()+" WHERE "+s.key()+"=?",id);}result.put(e.getKey(),count);}
  int days=policy.days().get("CALENDAR");int count=p.db.update("DELETE FROM listener_calendar_rules WHERE id IN(SELECT r.id FROM listener_calendar_rules r WHERE LEAST(COALESCE(r.retired_at,'infinity'::timestamptz),(r.valid_until+1)::timestamp AT TIME ZONE r.timezone)<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM listener_bookings b WHERE b.rule_id=r.id) ORDER BY r.id LIMIT 100)",days);count+=p.db.update("DELETE FROM listener_calendar_exceptions WHERE id IN(SELECT e.id FROM listener_calendar_exceptions e WHERE LEAST(e.ends_at,COALESCE(e.retired_at,'infinity'::timestamptz))<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM listener_bookings b WHERE b.exception_id=e.id) ORDER BY e.id LIMIT 100)",days);count+=p.db.update("DELETE FROM listener_queue_coverage_windows WHERE id IN(SELECT id FROM listener_queue_coverage_windows WHERE LEAST(ends_at,COALESCE(revoked_at,'infinity'::timestamptz))<listener_support_now()-(?*INTERVAL '1 day') ORDER BY id LIMIT 100)",days);count+=p.db.update("DELETE FROM listener_calendar_settings s WHERE s.listener_id IN(SELECT s2.listener_id FROM listener_calendar_settings s2 WHERE s2.updated_at<listener_support_now()-(?*INTERVAL '1 day') AND NOT EXISTS(SELECT 1 FROM listener_calendar_rules r WHERE r.listener_id=s2.listener_id) AND NOT EXISTS(SELECT 1 FROM listener_calendar_exceptions e WHERE e.listener_id=s2.listener_id) AND NOT EXISTS(SELECT 1 FROM listener_bookings b WHERE b.listener_id=s2.listener_id) ORDER BY s2.listener_id LIMIT 100)",days);result.put("CALENDAR",count);
  p.db.update("DELETE FROM listener_session_warning_notices n WHERE n.session_id IN(SELECT r.id FROM live_support_requests r WHERE r.status IN('COMPLETED','ENDED_SAFETY') AND r.ended_at<listener_support_now()-(?*INTERVAL '1 day') ORDER BY r.id LIMIT 100)",policy.days().get("EXTENSION"));p.db.queryForObject("SELECT set_config('greenocean.listener_metadata_retention_days',?,TRUE)",String.class,policy.days().get("EXTENSION").toString());
  result.put("DURATION",p.db.update("UPDATE live_support_requests SET planned_seconds=NULL,planning_buffer_seconds=NULL,admission_until=NULL,planned_ends_at=NULL,extension_seconds_used=0 WHERE id IN(SELECT id FROM live_support_requests WHERE planned_seconds IS NOT NULL AND status IN('COMPLETED','ENDED_SAFETY','EXPIRED','CANCELLED','DECLINED') AND ended_at<listener_support_now()-(?*INTERVAL '1 day') ORDER BY id LIMIT 100)",policy.days().get("EXTENSION")));
  p.db.update("INSERT INTO listener_support_worker_state(name,last_success_at) VALUES('metadata-retention',listener_support_now()) ON CONFLICT(name) DO UPDATE SET last_success_at=EXCLUDED.last_success_at");return result;
 }
}
